-- BRP HQ demo seed (sample rows). Generated by backend/hq/tools/import-command-center.mjs. Upserts by id; safe to run again.
-- Run as the database owner (psql, or the Supabase connector's SQL tool). Rows with sample = false are hidden from demo accounts.
begin;
set local brp.hq_fn = 'on';
on conflict (id) do update set owner = excluded.owner, desk = excluded.desk, area = excluded.area, item = excluded.item, status = excluded.status, due = excluded.due, sort_date = excluded.sort_date, next = excluded.next, note = excluded.note, inst = excluded.inst, shared = excluded.shared, source = excluded.source, sample = excluded.sample;
on conflict (id) do update set kind = excluded.kind, question = excluded.question, context = excluded.context, options = excluded.options, recommended = excluded.recommended, owner = excluded.owner, answer = excluded.answer, answer_index = excluded.answer_index, answered_at = excluded.answered_at, sort_date = excluded.sort_date, shared = excluded.shared, source = excluded.source, sample = excluded.sample;
on conflict (id) do update set name = excluded.name, agent = excluded.agent, level = excluded.level, mode = excluded.mode, evidence = excluded.evidence, next = excluded.next, sort = excluded.sort, sample = excluded.sample;
on conflict (id) do update set name = excluded.name, status = excluded.status, state = excluded.state, url = excluded.url, note = excluded.note, sort = excluded.sort, sample = excluded.sample;
on conflict (id) do update set title = excluded.title, url = excluded.url, area = excluded.area, note = excluded.note, owner = excluded.owner, shared = excluded.shared, inst = excluded.inst, sort = excluded.sort, sample = excluded.sample;
commit;
