insert into public.hq_decisions (id, kind, question, context, options, recommended, owner, answer, answer_index, answered_at, sort_date, shared, source, sample) values
  ('d1', 'question', 'Should Claude write the xTech white paper v1 now? It is due Oct 19.', 'Only a v0 draft exists. Claude will leave out any claim we cannot document.', '["Yes, start now","No, skip xTech this round"]'::jsonb, 0, 'Andrew', null, null, null, '2026-10-14'::date, false, 'command_center', true),
  ('d2', 'question', 'Are the two CSM text claims true and documented?', 'The draft says BRP helped two posts, and that modernized barracks and funding are authorized as of Oct 1. If either can''t be backed up, Claude removes it.', '["Both true, I have proof","Remove those lines"]'::jsonb, 1, 'Andrew', null, null, null, '2026-10-15'::date, false, 'command_center', true),
  ('d3', 'question', 'Does the $500 per-order buyer cap stay fixed while weekly caps change?', 'Claude assumed it stays fixed. Only the weekly cap moves with the 3-month average.', '["Yes, fixed at $500","Let it grow with the weekly cap"]'::jsonb, 0, 'Andrew', null, null, null, '2026-10-16'::date, false, 'command_center', true),
  ('d4', 'question', 'When an installation''s 3-month average is above $2,500 a week, who approves the extra?', 'A site lead can approve up to $2,500. The kit sends anything above that to the program manager. Weeks run Monday to Sunday, Central time.', '["Program manager approves","Hold everyone at $2,500"]'::jsonb, 0, 'Andrew', null, null, null, '2026-10-16'::date, false, 'command_center', true),
  ('d5', 'question', 'Keep "G. Holt" as the invented DPW name in the demo?', 'It is a made-up demo account name, not a real person.', '["Keep G. Holt","Use a different name"]'::jsonb, 0, 'Andrew', null, null, null, '2026-10-17'::date, false, 'command_center', true),
  ('d6', 'question', 'Can agents tell Soldiers "don''t touch or disturb it" about suspected mold?', 'Right now agents only log it, give the humidity standard, and treat breathing trouble as medical. Claude will cite a health source before adding the line.', '["Yes, approve the line","No, leave it out"]'::jsonb, 0, 'Andrew', null, null, null, '2026-10-17'::date, false, 'command_center', true)
